#include <iostream>
#include <cctype>
#include <cstring>

void print_uppercase(const char* s) {
    std::cout << "Original: " << s << ", Upper: ";
    for (size_t i = 0; s[i] != '\0'; ++i) {
        std::cout << static_cast<char>(std::toupper(static_cast<unsigned char>(s[i])));
    }
    std::cout << "\n";
}

double square(double x) {
    return x * x;
}

int main() {
    const char text[] = "cpp17";
    print_uppercase(text);

    double (*fp)(double) = square;
    std::cout << "Square of 3.5: " << fp(3.5) << "\n";
    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

constexpr double EPS = 1.0e-5;

double bisect(double (*f)(double), double a, double b) {
    double c = (a + b) / 2.0;
    while (std::fabs(b - a) > EPS && std::fabs(f(c)) > 1.0e-9) {
        if (f(a) * f(c) > 0.0) {
            a = c;
        } else {
            b = c;
        }
        c = (a + b) / 2.0;
    }
    return c;
}

double f_exp(double x) {
    return std::exp(x) - 2.0;
}

double op_add(double a, double b) { return a + b; }
double op_sub(double a, double b) { return a - b; }
double op_mul(double a, double b) { return a * b; }
double op_div(double a, double b) { return b != 0.0 ? a / b : 0.0; }

int main() {
    std::cout << std::fixed << std::setprecision(4);
    double root = bisect(f_exp, 0.0, 1.0);
    std::cout << "Root of e^x - 2 = 0 on [0, 1]: " << root << "\n";

    double (*ops[4])(double, double) = { op_add, op_sub, op_mul, op_div };
    const char symbols[] = { '+', '-', '*', '/' };
    double x = 12.0, y = 4.0;
    for (int i = 0; i < 4; ++i) {
        std::cout << x << " " << symbols[i] << " " << y << " = " << ops[i](x, y) << "\n";
    }
    return 0;
}
